export const events = {
	appearanceCorners: (callback: (payload: Corners) => void) => listen<Corners>("appearance.corners", callback),
	appearanceMotion: (callback: (payload: Motion) => void) => listen<Motion>("appearance.motion", callback),
	appearanceTypography: (callback: (payload: Typography) => void) => listen<Typography>("appearance.typography", callback),
	kestrelPalette: (callback: (payload: import("@luft/ui").Palette) => void) => listen<import("@luft/ui").Palette>("kestrel.palette", callback),
	schelfLibrary: (callback: (payload: Finished) => void) => listen<Finished>("schelf.library", callback),
	schelfOperations: (callback: (payload: Operation[]) => void) => listen<Operation[]>("schelf.operations", callback),
};

export type Action = "install" | "remove" | "update";

export type AddedSource = {
	file: string,
	name: string,
	url: string,
	packages: string[],
};

export type AppState = {
	files: string[],
	page: string | null,
	fedora: boolean,
} & Appearance;

export type AppUpdate = {
	key: string,
	source: Source,
	id: string,
	desktop: string | null,
	name: string,
	icon: string | null,
	from: string | null,
	to: string | null,
	size: number,
	platform: boolean,
	installation: Installation | null,
	reference: string | null,
	package: string | null,
};

export type Appearance = {
	palette: import("@luft/ui").Palette | null,
	typography: Typography,
	motion: Motion,
	corners: Corners,
	locale: Locale,
};

/**  A repository and what the system said about it, to be trusted before it's added. */
export type CheckedSource = {
	draft: RepositoryDraft,
	described: Described,
	added: boolean,
};

export type Corners = "rounded" | "square";

/**
 *  What the system says about a draft: the sources in it and the keys their packages must be
 *  signed with.
 */
export type Described = {
	file: string,
	sources: DescribedSource[],
	keys: SourceKey[],
};

export type DescribedSource = {
	id: string,
	name: string,
	url: string,
};

export type FedoraApp = {
	details: PackageDetails | null,
} & FedoraComponent;

export type FedoraComponent = {
	id: string,
	package: string,
	name: string,
	summary: string,
	description: string,
	icon: string | null,
	categories: string[],
	keywords: string[],
	developer: string | null,
	license: string | null,
	homepage: string | null,
	screenshots: Screenshot[],
};

export type FedoraSummary = {
	id: string,
	package: string,
	name: string,
	summary: string,
	icon: string | null,
	categories: string[],
	keywords: string[],
	screenshots: number,
};

export type Finished = {
	keys: string[],
	action: Action,
	succeeded: boolean,
};

export type Installation = "user" | "system";

export type InstalledApp = {
	key: string,
	source: Source,
	id: string,
	desktop: string | null,
	name: string,
	summary: string | null,
	icon: string | null,
	version: string | null,
	size: number,
	origin: string,
	installation: Installation | null,
	reference: string | null,
	package: string | null,
	path: string | null,
	commands: string[],
	services: string[],
};

